get_ipython().run_cell_magic('writefile', f'{STAGING}/e5_ablation_core.py', '"""E5B shared validation, whole-head ablation, and generation bookkeeping."""\nimport contextlib\nimport hashlib\nimport json\nfrom pathlib import Path\nfrom collections import Counter\nimport numpy as np\n\nCONDITIONS = [\'baseline\', \'top_target_effect\', \'random_1\', \'random_2\', \'random_3\']\n\n\ndef require(value, message):\n    if not bool(value):\n        raise ValueError(message)\n\n\ndef sha_file(path):\n    h = hashlib.sha256()\n    with Path(path).open(\'rb\') as stream:\n        for block in iter(lambda: stream.read(1024*1024), b\'\'):\n            h.update(block)\n    return h.hexdigest()\n\n\ndef digest(value):\n    return hashlib.sha256(str(value).encode()).hexdigest()\n\n\ndef canonical(value):\n    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(\',\', \':\')).encode()).hexdigest()\n\n\ndef verify_manifest(root, manifest_name=\'completed_all.json\'):\n    root = Path(root)\n    value = json.loads((root/manifest_name).read_text())\n    for name, expected in value[\'files\'].items():\n        target = (root/name).resolve()\n        require(target.is_relative_to(root.resolve()), \'Manifest path escapes the expected directory\')\n        require(sha_file(target) == expected, \'Changed upstream result: \'+name)\n    return value\n\n\ndef validate_sets(selection):\n    layers, heads = selection[\'layer_count\'], selection[\'heads_per_layer\']\n    require(list(selection[\'sets\']) == CONDITIONS, \'Unexpected condition order/set names\')\n    sets = {}\n    for name, entries in selection[\'sets\'].items():\n        values = [(int(row[\'layer\']), int(row[\'head\'])) for row in entries]\n        require(len(set(values)) == len(values), \'Duplicate head in \'+name)\n        require(all(0 <= l < layers and 0 <= h < heads for l, h in values), \'Head index outside architecture\')\n        require(all(row[\'flat_head\'] == row[\'layer\']*heads+row[\'head\'] for row in entries), \'Flat-head mapping changed\')\n        sets[name] = values\n    top = sets[\'top_target_effect\']\n    require(len(top) == int(np.ceil(.1*layers*heads)), \'Frozen top-set size changed\')\n    for name in CONDITIONS[2:]:\n        require(len(sets[name]) == len(top) and not set(top)&set(sets[name]), \'Random/top sets overlap or differ in size\')\n        require(Counter(l for l, _ in sets[name]) == Counter(l for l, _ in top), \'Random control is not layer-matched\')\n    require(len({tuple(sets[name]) for name in CONDITIONS[2:]}) == 3, \'Random controls are not distinct\')\n    require(not sets[\'baseline\'], \'Baseline must be unablated\')\n    return sets\n\n\ndef cross_attention_modules(model, study):\n    if study == \'madlad\':\n        modules = [block.layer[1].EncDecAttention for block in model.decoder.block]\n        specs = [(m, m.o, int(m.n_heads), int(m.key_value_proj_dim)) for m in modules]\n    else:\n        modules = [layer.encoder_attn for layer in model.model.decoder.layers]\n        specs = [(m, m.out_proj, int(m.num_heads), int(m.head_dim)) for m in modules]\n    require(specs and all(proj.in_features == heads*dim for _, proj, heads, dim in specs),\n            \'Cross-attention projection does not use contiguous concatenated head blocks\')\n    return specs\n\n\nclass HeadAblation:\n    """Zero selected head contexts immediately before the shared output projection.\n\n    This equals the native post-softmax head mask, without renormalization.\n    Attention probabilities are still computed and returned for disabled heads;\n    use the saved activity mask to distinguish them from contributing heads.\n    Self-attention, encoder states, projection bias and model weights are intact.\n    """\n    def __init__(self, model, study, selection):\n        self.specs = cross_attention_modules(model, study)\n        self.layers = len(self.specs)\n        self.heads = self.specs[0][2]\n        require(self.layers == selection[\'layer_count\'] and self.heads == selection[\'heads_per_layer\'],\n                \'Runtime architecture disagrees with frozen E5A head mapping\')\n        require(all(h == self.heads for _, _, h, _ in self.specs), \'Variable head count not supported\')\n        self.calls = {}\n        self.zero_errors = []\n\n    @contextlib.contextmanager\n    def activate(self, pairs, identity=False, audit=False):\n        import torch\n        self.calls = {}\n        self.zero_errors = []\n        handles = []\n        wanted = set(pairs)\n        require(all(0 <= l < self.layers and 0 <= h < self.heads for l, h in wanted), \'Invalid ablation mapping\')\n        try:\n            for layer, (_, projection, heads, dim) in enumerate(self.specs):\n                chosen = sorted(h for l, h in wanted if l == layer)\n                if not chosen and not identity:\n                    continue\n                def hook(module, inputs, layer=layer, chosen=chosen, heads=heads, dim=dim):\n                    require(len(inputs) == 1, \'Unexpected cross-attention output-projection signature\')\n                    value = inputs[0]\n                    require(value.dtype == torch.float32 and value.shape[-1] == heads*dim,\n                            \'Expected fp32 concatenated head context\')\n                    shaped = value.reshape(*value.shape[:-1], heads, dim)\n                    if identity:\n                        modified = shaped * torch.ones((heads, 1), device=value.device, dtype=value.dtype)\n                    else:\n                        modified = shaped.clone()\n                        modified[..., chosen, :] = 0\n                    self.calls[layer] = self.calls.get(layer, 0)+1\n                    if audit and chosen:\n                        self.zero_errors.append(float(modified[..., chosen, :].abs().max()))\n                    return (modified.reshape_as(value),)\n                handles.append(projection.register_forward_pre_hook(hook))\n            yield self\n            expected_layers = set(range(self.layers)) if identity else {l for l, _ in wanted}\n            require(set(self.calls) == expected_layers, \'An ablation hook was not exercised on its decoder layer\')\n            require(not self.zero_errors or max(self.zero_errors) == 0, \'Selected head context was not exactly zero\')\n        finally:\n            for handle in handles:\n                handle.remove()\n\n    def native_mask(self, pairs, device):\n        import torch\n        mask = torch.ones((self.layers, self.heads), device=device, dtype=torch.float32)\n        for layer, head in pairs:\n            mask[layer, head] = 0\n        return mask\n\n\ndef trim_sequence(values, eos_id):\n    """Skip decoder-start position: NLLB can use EOS itself as decoder start."""\n    values = list(map(int, values))\n    endings = [i for i, value in enumerate(values) if i > 0 and value == int(eos_id)]\n    return values[:endings[0]+1] if endings else values\n\n\ndef generation_flags(text, reference, ids, eos_id, limit):\n    words = str(text).split()\n    triples = list(zip(words, words[1:], words[2:]))\n    repeated = bool(triples and max(Counter(triples).values()) >= 3)\n    empty = not str(text).strip()\n    token_loop = bool(len(words) >= 8 and Counter(words).most_common(1)[0][1]/len(words) > .5)\n    ends = len(ids) > 1 and int(ids[-1]) == int(eos_id)\n    return {\'empty_output\': empty, \'repeated_word_trigram\': repeated,\n            \'degenerate\': bool(empty or token_loop), \'ended_with_eos\': ends,\n            \'generation_hit_cap\': bool(not ends and len(ids) >= limit),\n            \'generated_length\': len(ids),\n            \'length_ratio_chars\': sum(not c.isspace() for c in str(text))/max(1, sum(not c.isspace() for c in str(reference)))}\n\n\ndef activity_mask(layers, heads, selected):\n    mask = np.ones((layers, heads), dtype=bool)\n    for layer, head in selected:\n        mask[layer, head] = False\n    require(mask.any(), \'No surviving cross-attention heads\')\n    return mask\n\n\ndef paired_bootstrap(values, repetitions, seed, family_size=1):\n    """values: meaning × contrast. All columns use the same meaning resamples."""\n    require(values.ndim == 2 and len(values) >= 2 and np.isfinite(values).all(), \'Invalid paired cluster matrix\')\n    rng = np.random.default_rng(seed)\n    samples = np.empty((repetitions, values.shape[1]))\n    for start in range(0, repetitions, 256):\n        count = min(256, repetitions-start)\n        weights = rng.multinomial(len(values), np.full(len(values), 1/len(values)), size=count)\n        samples[start:start+count] = weights@values/len(values)\n    lo, hi = np.quantile(samples, [.025, .975], axis=0)\n    flo, fhi = np.quantile(samples, [.025/family_size, 1-.025/family_size], axis=0)\n    return values.mean(0), lo, hi, flo, fhi\n')


