get_ipython().run_cell_magic('writefile', f'{STAGING}/e5_ablation_worker.py', '"""E5B fp32 whole-head intervention; TF attention, output-only generation."""\nimport argparse\nimport gc\nimport importlib.metadata\nimport inspect\nimport json\nimport os\nimport time\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nfrom e1_core import progress, atomic_csv, atomic_json, atomic_npz, freeze_json\nfrom e3_worker import load_texts, prepare_records, positions\nfrom e4_masks import FINE_COMPONENTS, finer_positions, aggregate_attention\nfrom e5_ablation_core import (CONDITIONS, require, sha_file, canonical, validate_sets,\n                              HeadAblation, trim_sequence, generation_flags, activity_mask)\n\n\ndef run(config):\n    require(os.environ.get(\'PYTHONHASHSEED\') == \'0\', \'Start the worker with PYTHONHASHSEED=0\')\n    for name, expected in config[\'source_hashes\'].items():\n        require(sha_file(Path(__file__).parent/name) == expected, \'Changed source: \'+name)\n    progress(\'Importing pinned fp32 GPU libraries...\')\n    import torch\n    from transformers import T5Tokenizer, T5ForConditionalGeneration\n    from huggingface_hub import snapshot_download\n    import sacrebleu\n    require(torch.cuda.is_available(), \'E5B requires an L4 GPU; CPU inference is not started\')\n    torch.manual_seed(config[\'seed\'])\n    np.random.seed(config[\'seed\'])\n    torch.backends.cuda.matmul.allow_tf32 = False\n    torch.backends.cudnn.allow_tf32 = False\n    torch.backends.cudnn.benchmark = False\n    torch.backends.cudnn.deterministic = True\n    torch.set_float32_matmul_precision(\'highest\')\n    study = config[\'study\']\n    root = Path(config[\'output\'])\n    root.mkdir(parents=True, exist_ok=True)\n    e4 = Path(config[\'e4_root\'])/\'collectors\'/study\n    selection = config[\'selection\']\n    sets = validate_sets(selection)\n    split = selection[\'split\']\n    ids = sorted(split[\'train\']+split[\'validation\']+split[\'test\'])\n    require(len(ids) == len(set(ids)) == 450, \'Changed meaning split\')\n    require(config[\'generation_ids\'] == sorted(config[\'generation_ids\']) and\n            len(set(config[\'generation_ids\'])) == 20 and set(config[\'generation_ids\']) <= set(split[\'test\']),\n            \'Generation must use the frozen 20 of 68 test meanings\')\n    baseline = pd.read_csv(e4/\'all_rows.csv\', dtype={\'corpus_sentence_id\': str})\n    require(sha_file(e4/\'all_rows.csv\') == config[\'e4_rows_sha256\'], \'E4 baseline changed\')\n    require(sha_file(e4/\'private_tokenization/input_ids.csv\') == config[\'token_ids_sha256\'], \'E4 frozen input IDs changed\')\n    token_frame = pd.read_csv(e4/\'private_tokenization/input_ids.csv\', dtype={\'corpus_sentence_id\': str})\n    frozen_tokens = {(r.pair, r.sentence_id): (json.loads(r.source_ids_json), json.loads(r.reference_ids_json))\n                     for r in token_frame.itertuples(index=False)}\n    require(len(frozen_tokens) == 18000, \'Incomplete E4 token manifest\')\n    old = baseline.set_index([\'pair\', \'sentence_id\'])\n    require(len(old) == 18000 and not old.index.duplicated().any(), \'Incomplete E4 TF baseline\')\n    manifest = pd.read_csv(config[\'manifest\'], dtype={\'corpus_sentence_id\': str})\n    require(sha_file(config[\'manifest\']) == config[\'manifest_sha256\'], \'Original source/reference manifest changed\')\n    records = prepare_records(manifest, load_texts(config))\n    require(len(records) == 18000, \'Expected complete original baseline450 × 40 directions\')\n    by_pair = {}\n    for record in records:\n        by_pair.setdefault(record[\'pair\'], []).append(record)\n    for group in by_pair.values():\n        group.sort(key=lambda r: r[\'sentence_id\'])\n        require([r[\'sentence_id\'] for r in group] == ids, \'Direction does not contain the frozen 450 meanings\')\n    pairs = sorted(by_pair)\n    require(len(pairs) == 40, \'Original 40-direction graph changed\')\n    require(set(old.index) == set(frozen_tokens) == {(r[\'pair\'], r[\'sentence_id\']) for r in records}, \'Input supports differ\')\n    e4_lock = json.loads((e4/\'run_lock.json\').read_text())\n    if study == \'it2\':\n        import sys\n        sys.path.insert(0, config[\'indic_library\'])\n        os.environ[\'INDIC_RESOURCES_PATH\'] = config[\'indic_resources\']\n    if study in [\'it2\', \'nllb\']:\n        from original_adapter import Adapter\n        ad = Adapter(study)\n        tok, model = ad.tok, ad.model\n        spec = {\'repo\': ad.name, \'revision\': ad.model_rev}\n    else:\n        spec = e4_lock[\'model\']\n        progress(\'Verifying cached pinned MADLAD weights...\')\n        directory = snapshot_download(spec[\'repo\'], revision=spec[\'revision\'], local_dir=config[\'madlad_cache\'],\n                                      allow_patterns=list(spec[\'files\']))\n        for name, expected in spec[\'files\'].items():\n            require(sha_file(Path(directory)/name) == expected, \'MADLAD asset changed: \'+name)\n        tok = T5Tokenizer.from_pretrained(directory, local_files_only=True, legacy=False)\n        model = T5ForConditionalGeneration.from_pretrained(directory, local_files_only=True, use_safetensors=True,\n            torch_dtype=torch.float32, low_cpu_mem_usage=True, attn_implementation=\'eager\', device_map={\'\': \'cuda:0\'}).eval()\n    require((spec[\'repo\'], spec[\'revision\']) == (selection[\'model\'][\'repo\'], selection[\'model\'][\'revision\']), \'Checkpoint differs from E5A\')\n    require(all(p.dtype == torch.float32 and p.device.type == \'cuda\' for p in model.parameters()), \'Expected wholly fp32 CUDA model\')\n    require(getattr(model.config, \'_attn_implementation\', \'eager\') == \'eager\', \'Eager attention required\')\n    require(tok.padding_side == e4_lock[\'tokenizer_padding_side\'], \'Tokenizer padding convention changed\')\n    patch = HeadAblation(model, study, selection)\n    require(\'cross_attn_head_mask\' in inspect.signature(model.forward).parameters,\n            \'Native head-mask reference unavailable; do not skip the intervention-equivalence smoke test\')\n    module_sources = {str(type(m).__name__): sha_file(inspect.getsourcefile(type(m))) for m, _, _, _ in patch.specs}\n    batch_size = 4 if study in [\'it2\', \'nllb\'] else 1\n    generation_batch_size = 4 if study in [\'it2\', \'nllb\'] else 1\n    generation_options = {\'max_length\': 256, \'min_length\': 0, \'num_beams\': 1, \'do_sample\': False,\n                          \'use_cache\': True, \'output_attentions\': False, \'output_scores\': False,\n                          \'return_dict_in_generate\': True}\n    signature = {\'study\': study, \'model\': spec, \'head_sets\': selection, \'generation_ids\': config[\'generation_ids\'],\n                 \'e4_rows_sha256\': config[\'e4_rows_sha256\'], \'token_ids_sha256\': config[\'token_ids_sha256\'],\n                 \'manifest_sha256\': config[\'manifest_sha256\'], \'source_hashes\': config[\'source_hashes\'],\n                 \'seed\': config[\'seed\'], \'python_hash_seed\': 0, \'precision\': \'fp32\', \'TF32\': False,\n                 \'attention\': \'eager\', \'TF_batch_policy\': \'same original450 groups of4; MADLAD singleton; \'\n                 \'score test68 only, unscored neighbors reproduce original padding\',\n                 \'generation_batch_size\': generation_batch_size, \'generation\': generation_options,\n                 \'ablation\': \'zero selected concatenated head contexts before output projection; no renormalization\',\n                 \'attention_reporting\': \'all computed probabilities still close to1 per head; \'\n                 \'save active-head mask, all-head means and normalized surviving-head means separately\',\n                 \'native_equivalence_tolerance\': 1e-5, \'E4_baseline_tolerance\': 1e-5,\n                 \'module_source_sha256\': module_sources, \'gpu\': torch.cuda.get_device_name(0),\n                 \'packages\': {p: importlib.metadata.version(p) for p in\n                              [\'torch\', \'transformers\', \'numpy\', \'pandas\', \'sentencepiece\', \'sacrebleu\']}}\n    freeze_json(root/\'run_lock.json\', signature)\n    fingerprint = canonical(signature)\n    frozen_by_key = {(r[\'pair\'], r[\'sentence_id\']): r for r in records}\n    context = {}\n    for pair, group in by_pair.items():\n        for start in range(0, 450, batch_size):\n            block = group[start:start+batch_size]\n            for record in block:\n                context[(pair, record[\'sentence_id\'])] = block\n\n    def verify_ids(x, y, block):\n        for member, record in enumerate(block):\n            a = x.input_ids[member][x.attention_mask[member].bool()].tolist()\n            b = y.input_ids[member][y.attention_mask[member].bool()].tolist()\n            require((a, b) == frozen_tokens[(record[\'pair\'], record[\'sentence_id\'])], \'Token IDs differ from deterministic E4\')\n\n    def encode(block):\n        record = block[0]\n        if study in [\'it2\', \'nllb\']:\n            x, y = ad.encode(record[\'source\'], record[\'target\'], record[\'target\'],\n                             [r[\'src_text\'] for r in block], [r[\'tgt_text\'] for r in block])\n        else:\n            require(len(block) == 1, \'MADLAD TF must retain original singleton context\')\n            x = tok(\'<2\'+config[\'language_codes\'][record[\'target\']]+\'> \'+record[\'src_text\'], return_tensors=\'pt\', truncation=False)\n            y = tok(record[\'tgt_text\'], return_tensors=\'pt\', truncation=False)\n        verify_ids(x, y, block)\n        labels = y.input_ids.clone()\n        labels[y.attention_mask == 0] = -100\n        return x, y, labels\n\n    def forward(x, labels, native=None):\n        options = {\'use_cache\': False} if study == \'madlad\' else {}\n        if native is not None:\n            options[\'cross_attn_head_mask\'] = native\n        return model(input_ids=x.input_ids.cuda(), attention_mask=x.attention_mask.cuda(), labels=labels.cuda(),\n                     output_attentions=True, return_dict=True, **options)\n\n    def tf_rows(out, x, y, labels, block, wanted, condition):\n        rows, heads = [], []\n        active = activity_mask(patch.layers, patch.heads, sets[condition])\n        for member, record in enumerate(block):\n            if record[\'sentence_id\'] not in wanted:\n                continue\n            source_ids, source_mask = x.input_ids[member].tolist(), x.attention_mask[member].tolist()\n            if study in [\'it2\', \'nllb\']:\n                base = ad.categories(source_ids, source_mask, record[\'source\'], record[\'target\'])\n                positions_y = ad.target_rows(y.input_ids[member].tolist(), y.attention_mask[member].tolist(), record[\'target\'])\n                pieces = ad.pieces(source_ids)\n            else:\n                prefix_id = tok.convert_tokens_to_ids(\'<2\'+config[\'language_codes\'][record[\'target\']]+\'>\')\n                base = positions(tok, source_ids, source_mask, prefix_id)\n                positions_y = positions(tok, y.input_ids[member].tolist(), y.attention_mask[member].tolist())[\'lexical\']\n                pieces = tok.convert_ids_to_tokens(source_ids)\n            require(len(positions_y) == int(old.loc[(record[\'pair\'], record[\'sentence_id\'])].target_lexical_pieces),\n                    \'E4 reference target-row support changed\')\n            fine = finer_positions(base, source_ids, pieces, int(tok.unk_token_id))\n            shares, closure = aggregate_attention(tuple(a[member:member+1] for a in out.cross_attentions), fine, positions_y)\n            all_means = shares.mean((0, 1), dtype=np.float64)\n            surviving = shares[active].mean(0, dtype=np.float64)\n            losses = torch.nn.functional.cross_entropy(out.logits[member].float(), labels[member].cuda(),\n                                                       reduction=\'none\', ignore_index=-100)\n            nll = float(losses[positions_y].mean())\n            sequence_nll = float(losses[labels[member].ne(-100).cuda()].mean())\n            require(np.isfinite([nll, sequence_nll]).all(), \'Nonfinite reference NLL; stop without dropping the row\')\n            row = {key: record[key] for key in [\'pair\', \'sentence_id\', \'corpus_sentence_id\', \'source\', \'target\']}\n            row.update({\'condition\': condition, \'reference_lexical_tokens\': len(positions_y), \'lexical_NLL\': nll,\n                        \'sequence_NLL\': sequence_nll, \'closure_maxerr\': closure, \'active_head_fraction\': float(active.mean())})\n            row.update({\'all_computed_\'+name: float(v) for name, v in zip(FINE_COMPONENTS, all_means)})\n            row.update({\'surviving_\'+name: float(v) for name, v in zip(FINE_COMPONENTS, surviving)})\n            row[\'surviving_LM\'] = row[\'surviving_content\']+(row[\'surviving_unknown\'] if study == \'nllb\' else 0.)\n            if condition == \'baseline\':\n                expected = old.loc[(record[\'pair\'], record[\'sentence_id\'])]\n                delta = float(np.max(np.abs(all_means-expected[FINE_COMPONENTS].to_numpy(float))))\n                require(delta <= 1e-5, f\'E4 same-input baseline reproduction failed: {record["pair"]} / {record["sentence_id"]}, {delta}\')\n                row[\'E4_baseline_max_component_delta\'] = delta\n            else:\n                row[\'E4_baseline_max_component_delta\'] = np.nan\n            rows.append(row)\n            heads.append(shares)\n        return rows, heads\n\n    def generate(block, condition, identity=False):\n        record = block[0]\n        ip = None\n        if study == \'it2\':\n            ip = ad.IndicProcessor(inference=True)\n            preprocessed = ip.preprocess_batch([r[\'src_text\'] for r in block], src_lang=record[\'source\'], tgt_lang=record[\'target\'])\n            x = tok(preprocessed, return_tensors=\'pt\', padding=True, truncation=True, max_length=256, return_attention_mask=True)\n        elif study == \'nllb\':\n            tok.src_lang = record[\'source\']\n            tok.tgt_lang = record[\'target\']\n            tok.set_src_lang_special_tokens(record[\'source\'])\n            x = tok([r[\'src_text\'] for r in block], return_tensors=\'pt\', padding=True, truncation=True, max_length=256,\n                    return_attention_mask=True)\n        else:\n            prefix = \'<2\'+config[\'language_codes\'][record[\'target\']]+\'>\'\n            x = tok([prefix+\' \'+r[\'src_text\'] for r in block], return_tensors=\'pt\', padding=True, truncation=False)\n        for member, r in enumerate(block):\n            actual = x.input_ids[member][x.attention_mask[member].bool()].tolist()\n            require(actual == frozen_tokens[(r[\'pair\'], r[\'sentence_id\'])][0], \'Generation encoder IDs differ from E4\')\n        options = dict(generation_options)\n        if study == \'nllb\':\n            options[\'forced_bos_token_id\'] = ad.language_id(record[\'target\'])\n        with patch.activate(sets[condition], identity=identity), torch.inference_mode():\n            result = model.generate(input_ids=x.input_ids.cuda(), attention_mask=x.attention_mask.cuda(), **options)\n        sequences = [trim_sequence(seq.tolist(), tok.eos_token_id) for seq in result.sequences]\n        if study == \'nllb\':\n            require(all(len(seq) >= 2 and seq[1] == ad.language_id(record[\'target\']) for seq in sequences), \'Forced target tag missing\')\n        decoded = tok.batch_decode(result.sequences, skip_special_tokens=True, clean_up_tokenization_spaces=(study == \'it2\'))\n        if ip is not None:\n            decoded = ip.postprocess_batch(decoded, lang=record[\'target\'])\n        require(len(decoded) == len(sequences) == len(block), \'Generation/postprocessing returned an incomplete batch\')\n        rows = []\n        for r, text, sequence in zip(block, decoded, sequences):\n            row = {key: r[key] for key in [\'pair\', \'sentence_id\', \'corpus_sentence_id\', \'source\', \'target\']}\n            row.update({\'condition\': condition, \'source_text\': r[\'src_text\'], \'reference\': r[\'tgt_text\'], \'hypothesis\': str(text),\n                        \'generated_ids_json\': json.dumps(sequence), \'hyp_sha256\': canonical(str(text)),\n                        \'source_sha256\': canonical(r[\'src_text\']), \'reference_sha256\': canonical(r[\'tgt_text\']),\n                        \'chrfpp\': float(sacrebleu.sentence_chrf(str(text), [r[\'tgt_text\']], word_order=2).score)})\n            row.update(generation_flags(str(text), r[\'tgt_text\'], sequence, tok.eos_token_id, 256))\n            rows.append(row)\n        del result\n        return rows\n\n    # Smoke uses validation meanings, not the 68 test meanings or 20 quality meanings.\n    progress(study+\': verifying unpatched/identity/native-mask equivalence and E4 baseline...\')\n    smoke_deltas = []\n    with torch.inference_mode():\n        for target in config[\'languages\']:\n            pair = next(p for p in pairs if p.split(\'__\')[1] == target)\n            block = context[(pair, split[\'validation\'][0])]\n            x, y, labels = encode(block)\n            original = forward(x, labels)\n            checked, _ = tf_rows(original, x, y, labels, block, {r[\'sentence_id\'] for r in block}, \'baseline\')\n            smoke_deltas.extend(r[\'E4_baseline_max_component_delta\'] for r in checked)\n            del original\n        probe = context[(pairs[0], split[\'validation\'][0])]\n        x, y, labels = encode(probe)\n        original = forward(x, labels)\n        reference_logits = original.logits.detach().clone()\n        del original\n        with patch.activate([], identity=True):\n            identical = forward(x, labels)\n        require(torch.equal(reference_logits, identical.logits), \'Identity hook changed TF logits\')\n        del identical, reference_logits\n        equivalence = {}\n        for name in CONDITIONS[1:]:\n            with patch.activate(sets[name], audit=True):\n                hooked = forward(x, labels)\n            reference_logits = hooked.logits.detach().clone()\n            del hooked\n            native = forward(x, labels, native=patch.native_mask(sets[name], \'cuda\'))\n            difference = float((reference_logits-native.logits).abs().max())\n            require(difference <= 1e-5, \'Whole-head hook disagrees with native head mask: \'+name)\n            equivalence[name] = difference\n            del native, reference_logits\n    smoke_generation = []\n    durations = []\n    for pair in pairs[:2]:\n        probe = [frozen_by_key[(pair, split[\'validation\'][0])]]\n        start = time.perf_counter()\n        normal = generate(probe, \'baseline\')\n        identity_result = generate(probe, \'baseline\', identity=True)\n        require(normal[0][\'generated_ids_json\'] == identity_result[0][\'generated_ids_json\'], \'Identity hook changed greedy token IDs\')\n        smoke_generation.extend(normal)\n        for name in CONDITIONS[1:]:\n            tic = time.perf_counter()\n            smoke_generation.extend(generate(probe, name))\n            durations.append(time.perf_counter()-tic)\n        progress(f\'{study}: generation smoke pair {pair}; {time.perf_counter()-start:.1f}s\')\n    atomic_csv(root/\'private_generation/smoke_validation_outputs.csv\', pd.DataFrame(smoke_generation))\n    report = {\'passed\': True, \'validation_only\': True, \'identity_TF_logits_bit_identical\': True,\n              \'identity_greedy_IDs_identical\': True, \'max_E4_component_delta\': max(smoke_deltas),\n              \'native_head_mask_max_logit_deltas\': equivalence,\n              \'timed_generation_rows\': len(durations), \'seconds_per_singleton_generation\': float(np.mean(durations)),\n              \'conservative_singleton_generation_hours_for_4000\': float(np.mean(durations)*4000/3600),\n              \'estimate_excludes\': \'setup, TF, COMET/LID and Drive; batching can reduce generation cost\',\n              \'peak_gpu_GiB\': torch.cuda.max_memory_allocated()/2**30}\n    atomic_json(root/\'smoke_report.json\', report)\n    progress(f\'{study}: smoke passed; singleton-based generation estimate {report["conservative_singleton_generation_hours_for_4000"]:.2f} h for 4,000 rows\')\n    tf_frames, gen_frames = [], []\n    test_ids = set(split[\'test\'])\n    generation_ids = set(config[\'generation_ids\'])\n    for pi, pair in enumerate(pairs, 1):\n        group = by_pair[pair]\n        encoded = {}\n        for condition in CONDITIONS:\n            folder = root/\'parts\'/pair/condition\n            folder.mkdir(parents=True, exist_ok=True)\n            tf_path, tf_npz = folder/\'tf.csv\', folder/\'heads.npz\'\n            tf_done = folder/\'tf_complete.json\'\n            if tf_done.is_file():\n                saved = json.loads(tf_done.read_text())\n                require(saved[\'fingerprint\'] == fingerprint and sha_file(tf_path) == saved[\'csv_sha256\'] and\n                        sha_file(tf_npz) == saved[\'npz_sha256\'], \'TF checkpoint changed\')\n                tf_frame = pd.read_csv(tf_path, dtype={\'corpus_sentence_id\': str})\n            else:\n                batch_rows, batch_heads = [], []\n                tic = time.perf_counter()\n                with patch.activate(sets[condition]), torch.inference_mode():\n                    for start in range(0, 450, batch_size):\n                        block = group[start:start+batch_size]\n                        if not test_ids.intersection(r[\'sentence_id\'] for r in block):\n                            continue\n                        if start not in encoded:\n                            encoded[start] = encode(block)\n                        x, y, labels = encoded[start]\n                        out = forward(x, labels)\n                        new, heads = tf_rows(out, x, y, labels, block, test_ids, condition)\n                        batch_rows.extend(new)\n                        batch_heads.extend(heads)\n                        del out\n                tf_frame = pd.DataFrame(batch_rows).sort_values(\'sentence_id\')\n                require(len(tf_frame) == 68 and tf_frame.sentence_id.tolist() == sorted(test_ids), \'Incomplete TF condition\')\n                # Iteration already visits original sorted meaning order.\n                atomic_csv(tf_path, tf_frame)\n                atomic_npz(tf_npz, shares=np.stack(batch_heads), columns=np.array(FINE_COMPONENTS, dtype=\'U24\'),\n                           sentence_id=np.array(tf_frame.sentence_id, dtype=np.int64),\n                           active_heads=activity_mask(patch.layers, patch.heads, sets[condition]))\n                atomic_json(tf_done, {\'fingerprint\': fingerprint, \'csv_sha256\': sha_file(tf_path), \'npz_sha256\': sha_file(tf_npz)})\n                progress(f\'{study} {pi}/40 {pair} {condition}: TF 68/68; {time.perf_counter()-tic:.1f}s\')\n            tf_frames.append(tf_frame)\n            gen_path = folder/\'private_generation/outputs.csv\'\n            gen_stamp = folder/\'generation_progress.json\'\n            if gen_stamp.is_file():\n                saved = json.loads(gen_stamp.read_text())\n                require(saved[\'fingerprint\'] == fingerprint and sha_file(gen_path) == saved[\'csv_sha256\'], \'Generation checkpoint changed\')\n                generated = pd.read_csv(gen_path, dtype={\'corpus_sentence_id\': str}, keep_default_na=False)\n                require(not generated.sentence_id.duplicated().any() and set(generated.sentence_id) <= generation_ids,\n                        \'Changed generation checkpoint support\')\n            else:\n                generated = pd.DataFrame()\n            have = set(generated.sentence_id) if len(generated) else set()\n            remaining = [r for r in group if r[\'sentence_id\'] in generation_ids-have]\n            tic = time.perf_counter()\n            for start in range(0, len(remaining), generation_batch_size):\n                block = remaining[start:start+generation_batch_size]\n                new = generate(block, condition)\n                generated = pd.concat([generated, pd.DataFrame(new)], ignore_index=True)\n                generated = generated.sort_values(\'sentence_id\')\n                atomic_csv(gen_path, generated)\n                atomic_json(gen_stamp, {\'fingerprint\': fingerprint, \'csv_sha256\': sha_file(gen_path), \'rows\': len(generated)})\n                progress(f\'{study} {pi}/40 {pair} {condition}: generation {len(generated)}/20; {time.perf_counter()-tic:.1f}s\')\n            require(len(generated) == 20 and set(generated.sentence_id) == generation_ids, \'Incomplete generation condition\')\n            gen_frames.append(generated)\n        gc.collect()\n        torch.cuda.empty_cache()\n    tf = pd.concat(tf_frames, ignore_index=True)\n    generation = pd.concat(gen_frames, ignore_index=True)\n    key = [\'pair\', \'sentence_id\', \'condition\']\n    require(len(tf) == 13600 and not tf.duplicated(key).any(), \'Incomplete TF intervention grid\')\n    require(len(generation) == 4000 and not generation.duplicated(key).any(), \'Incomplete generation intervention grid\')\n    atomic_csv(root/\'teacher_forced.csv\', tf)\n    atomic_csv(root/\'private_generation/all_outputs.csv\', generation)\n    atomic_json(root/\'complete.json\', {\'fingerprint\': fingerprint, \'run_lock_sha256\': sha_file(root/\'run_lock.json\'),\n                                      \'TF_sha256\': sha_file(root/\'teacher_forced.csv\'),\n                                      \'generation_sha256\': sha_file(root/\'private_generation/all_outputs.csv\'),\n                                      \'TF_rows\': len(tf), \'generation_rows\': len(generation)})\n    progress(study+\': collection complete; no generation attention requested; no rows silently removed\')\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--config\', required=True)\n    run(json.loads(Path(parser.parse_args().config).read_text()))\n')


