get_ipython().run_cell_magic('writefile', f'{STAGING}/e5_ablation_score.py', '"""E5B score new fixed-condition outputs using the same pinned COMET and GlotLID."""\nimport argparse\nimport importlib.metadata\nimport json\nimport time\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nfrom e1_core import progress, atomic_csv, atomic_json, freeze_json\nfrom e3_worker import load_texts, prepare_records\nfrom e2_worker import score_adaptive, token_audit\nfrom e5_ablation_core import require, sha_file, canonical, CONDITIONS\n\n\ndef run(config):\n    import torch\n    import fasttext\n    from huggingface_hub import snapshot_download, hf_hub_download\n    from comet.models.regression.regression_metric import RegressionMetric\n    for name, expected in config[\'source_hashes\'].items():\n        require(sha_file(Path(__file__).parent/name) == expected, \'Changed quality-scoring source: \'+name)\n    require(torch.cuda.is_available(), \'COMET needs the L4 GPU; no slow CPU fallback\')\n    torch.manual_seed(config[\'seed\'])\n    torch.backends.cuda.matmul.allow_tf32 = False\n    torch.backends.cudnn.allow_tf32 = False\n    torch.set_float32_matmul_precision(\'highest\')\n    root = Path(config[\'output\'])\n    root.mkdir(parents=True, exist_ok=True)\n    wide = load_texts(config)\n    manifest = pd.read_csv(config[\'manifest\'], dtype={\'corpus_sentence_id\': str})\n    require(sha_file(config[\'manifest\']) == config[\'manifest_sha256\'], \'Original corpus identity changed\')\n    original = {(r[\'pair\'], r[\'sentence_id\']): r for r in prepare_records(manifest, wide)}\n    frames = {}\n    inputs = {}\n    unique = {}\n    for study in config[\'studies\']:\n        collector = Path(config[\'collector_root\'])/study\n        complete = json.loads((collector/\'complete.json\').read_text())\n        path = collector/\'private_generation/all_outputs.csv\'\n        require(sha_file(path) == complete[\'generation_sha256\'], \'Generated output file changed: \'+study)\n        frame = pd.read_csv(path, dtype={\'corpus_sentence_id\': str}, keep_default_na=False)\n        require(len(frame) == 4000 and not frame.duplicated([\'pair\', \'sentence_id\', \'condition\']).any(), \'Incomplete generation grid\')\n        require(set(frame.condition) == set(CONDITIONS) and set(frame.sentence_id) == set(config[\'generation_ids\']), \'Changed generation support\')\n        keys = []\n        for row in frame.itertuples(index=False):\n            source = original[(row.pair, row.sentence_id)]\n            require(row.source_text == source[\'src_text\'] and row.reference == source[\'tgt_text\'] and\n                    str(row.corpus_sentence_id) == source[\'corpus_sentence_id\'], \'Source/reference corpus identity differs\')\n            require(row.source_sha256 == canonical(row.source_text) and row.reference_sha256 == canonical(row.reference) and\n                    row.hyp_sha256 == canonical(row.hypothesis), \'Generated/scoring text hashes disagree\')\n            key = canonical([row.source_text, row.hypothesis, row.reference])\n            record = {\'src\': row.source_text, \'mt\': row.hypothesis, \'ref\': row.reference}\n            require(key not in unique or unique[key] == record, \'Metric-input hash collision\')\n            unique[key] = record\n            keys.append(key)\n        frame[\'metric_input_id\'] = keys\n        frames[study] = frame\n        inputs[study] = sha_file(path)\n    spec = config[\'metric\']\n    metric_directory = Path(config[\'metric_cache\'])/(\'COMET_\'+spec[\'revision\'][:12])\n    encoder_directory = Path(config[\'metric_cache\'])/(\'XLMR_assets_\'+spec[\'encoder_revision\'][:12])\n    progress(\'Loading the same pinned WMT22 COMET model used in E2...\')\n    model_dir = snapshot_download(spec[\'repo\'], revision=spec[\'revision\'], local_dir=str(metric_directory),\n                                  allow_patterns=[\'checkpoints/model.ckpt\', \'hparams.yaml\'])\n    encoder_dir = snapshot_download(spec[\'encoder_repo\'], revision=spec[\'encoder_revision\'], local_dir=str(encoder_directory),\n                                   allow_patterns=[\'config.json\', \'tokenizer.json\', \'tokenizer_config.json\',\n                                                   \'special_tokens_map.json\', \'sentencepiece.bpe.model\'])\n    checkpoint = Path(model_dir)/\'checkpoints/model.ckpt\'\n    require(sha_file(checkpoint) == spec[\'checkpoint_sha256\'], \'COMET checkpoint checksum changed\')\n    model = RegressionMetric.load_from_checkpoint(str(checkpoint), map_location=\'cpu\', strict=False,\n                load_pretrained_weights=False, local_files_only=True, pretrained_model=str(encoder_dir))\n    model.eval().float()\n    lid_spec = config[\'lid\']\n    old_lid = json.loads(Path(config[\'lid_lock\']).read_text())\n    require(old_lid == lid_spec, \'GlotLID revision differs from the earlier intervention\')\n    progress(\'Loading pinned GlotLID on CPU; no script-based language guesses...\')\n    lid_path = hf_hub_download(lid_spec[\'repo\'], lid_spec[\'filename\'], revision=lid_spec[\'revision\'])\n    lid = fasttext.load_model(lid_path)\n    signature = {\'metric\': spec, \'lid\': lid_spec, \'lid_file_sha256\': sha_file(lid_path),\n                 \'inputs\': inputs, \'source_hashes\': config[\'source_hashes\'], \'precision\': \'fp32\', \'TF32\': False,\n                 \'unique_metric_inputs\': len(unique), \'total_generated_rows\': sum(map(len, frames.values())),\n                 \'reuse_policy\': \'exact source/hypothesis/reference deduplication only; no score imputation\',\n                 \'packages\': {p: importlib.metadata.version(p) for p in\n                              [\'torch\', \'transformers\', \'numpy\', \'pandas\', \'unbabel-comet\', \'fasttext-wheel\']}}\n    freeze_json(root/\'metric_run_lock.json\', signature)\n    fingerprint = canonical(signature)\n    cached = {}\n    for path in sorted((root/\'parts\').glob(\'*.json\')):\n        saved = json.loads(path.read_text())\n        csv = path.with_suffix(\'.csv\')\n        require(saved[\'fingerprint\'] == fingerprint and sha_file(csv) == saved[\'csv_sha256\'], \'Changed COMET checkpoint\')\n        frame = pd.read_csv(csv)\n        require(np.isfinite(frame.comet).all(), \'Nonfinite cached COMET value\')\n        for row in frame.to_dict(\'records\'):\n            key = row[\'metric_input_id\']\n            require(key in unique and key not in cached, \'Invalid/duplicate cached COMET input\')\n            cached[key] = row\n    remaining = sorted(set(unique)-set(cached))\n    progress(f\'COMET: {len(unique):,} unique inputs for {sum(map(len, frames.values())):,} generated rows; {len(cached):,} cached\')\n    batch_size = 8\n    if remaining:\n        smoke = [unique[key] for key in remaining[:32]]\n        start = time.perf_counter()\n        a, batch_size = score_adaptive(model, smoke, batch_size)\n        b, _ = score_adaptive(model, smoke, 4)\n        require(np.max(np.abs(a-b)) < 2e-5, \'COMET batch-invariance smoke failed\')\n        require(np.std(a) > 1e-6 or len(smoke) < 4, \'COMET smoke scores are unexpectedly constant\')\n        progress(f\'COMET smoke: {len(smoke)/(time.perf_counter()-start):.1f} rows/s including repeat; starting resumable scoring\')\n    part_index = len(list((root/\'parts\').glob(\'*.json\')))\n    for start in range(0, len(remaining), 128):\n        keys = remaining[start:start+128]\n        records = [unique[key] for key in keys]\n        scores, batch_size = score_adaptive(model, records, batch_size)\n        audits, limit = token_audit(model, records)\n        frame = pd.DataFrame({\'metric_input_id\': keys, \'comet\': scores, \'metric_token_limit\': limit})\n        for name, values in audits.items():\n            frame[name] = values\n        path = root/\'parts\'/f\'part_{part_index:05d}.csv\'\n        atomic_csv(path, frame)\n        atomic_json(path.with_suffix(\'.json\'), {\'fingerprint\': fingerprint, \'csv_sha256\': sha_file(path)})\n        cached.update({r[\'metric_input_id\']: r for r in frame.to_dict(\'records\')})\n        part_index += 1\n        progress(f\'COMET unique scores {len(cached):,}/{len(unique):,}\')\n    scores = pd.DataFrame(cached.values())\n    require(len(scores) == len(unique) and scores.metric_input_id.is_unique, \'Incomplete unique COMET labels\')\n    for study, frame in frames.items():\n        scored = frame.merge(scores, on=\'metric_input_id\', how=\'left\', validate=\'many_to_one\')\n        require(len(scored) == 4000 and np.isfinite(scored.comet).all(), \'Incomplete expanded COMET labels\')\n        labels, probabilities = [], []\n        for text in scored.hypothesis:\n            if str(text).strip():\n                label, probability = lid.predict(str(text).replace(\'\\n\', \' \'), k=1)\n                labels.append(label[0].replace(\'__label__\', \'\'))\n                probabilities.append(float(probability[0]))\n            else:\n                labels.append(\'EMPTY\')\n                probabilities.append(0.)\n        scored[\'lid_label\'] = labels\n        scored[\'lid_probability\'] = probabilities\n        scored[\'off_target\'] = scored.lid_label != scored.target\n        baseline = scored[scored.condition == \'baseline\'].set_index([\'pair\', \'sentence_id\'])\n        scored[\'changed_greedy_output\'] = [r.generated_ids_json != baseline.loc[(r.pair, r.sentence_id), \'generated_ids_json\']\n                                          for r in scored.itertuples(index=False)]\n        scored[\'changed_text\'] = [r.hyp_sha256 != baseline.loc[(r.pair, r.sentence_id), \'hyp_sha256\']\n                                 for r in scored.itertuples(index=False)]\n        private = root/study/\'private_generation/scored_outputs.csv\'\n        atomic_csv(private, scored)\n        public = scored.drop(columns=[\'source_text\', \'reference\', \'hypothesis\', \'generated_ids_json\'])\n        path = root/study/\'generation_scored.csv\'\n        atomic_csv(path, public)\n        atomic_json(root/study/\'complete.json\', {\'fingerprint\': fingerprint, \'input_sha256\': inputs[study],\n                    \'scores_sha256\': sha_file(path), \'private_scores_sha256\': sha_file(private), \'rows\': len(scored),\n                    \'empty_outputs\': int(scored.empty_output.astype(str).str.lower().eq(\'true\').sum()),\n                    \'metric_truncation_counts\': {column: int(scored[column].astype(str).str.lower().isin([\'true\', \'1\']).sum())\n                     for column in [\'source_truncated\', \'hypothesis_truncated\', \'reference_truncated\']}})\n        progress(study+\': COMET, chrF++ and GlotLID complete; cap-hit/empty outputs retained\')\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--config\', required=True)\n    run(json.loads(Path(parser.parse_args().config).read_text()))\n')


