get_ipython().run_cell_magic('writefile', f'{STAGING}/e5_ablation_analysis.py', '"""E5B paired meaning-clustered behavioral effects; no retraining or head selection."""\nimport argparse\nimport json\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nfrom e1_core import atomic_csv, atomic_json, progress\nfrom e5_ablation_core import CONDITIONS, require, sha_file, paired_bootstrap\n\n\ndef bool_column(series):\n    return series.astype(str).str.lower().isin([\'true\', \'1\', \'1.0\'])\n\n\ndef compare(frame, metrics, stage, study, repetitions, seed, scope=\'all_directions\', family_size=1):\n    contrasts, per_meaning = [], []\n    for metric in metrics:\n        pivot = frame.pivot(index=[\'sentence_id\', \'pair\'], columns=\'condition\', values=metric).reindex(columns=CONDITIONS)\n        require(pivot.notna().all().all(), \'A paired condition is missing; no imputation\')\n        baseline = pivot[\'baseline\']\n        top = pivot[\'top_target_effect\']\n        random = pivot[[\'random_1\', \'random_2\', \'random_3\']].mean(1)\n        quality = metric in [\'comet\', \'chrfpp\']\n        sign = 1 if quality else -1\n        differences = pd.DataFrame({\'selected_vs_baseline\': sign*(baseline-top),\n                                    \'random_mean_vs_baseline\': sign*(baseline-random),\n                                    \'selected_vs_random_mean\': sign*(random-top)})\n        means = differences.groupby(\'sentence_id\').mean().sort_index()\n        point, low, high, flo, fhi = paired_bootstrap(means.to_numpy(), repetitions, seed, family_size)\n        for j, name in enumerate(means):\n            primary = stage == \'generation\' and metric == \'comet\' and name == \'selected_vs_random_mean\' and scope == \'all_directions\'\n            contrasts.append({\'study\': study, \'stage\': stage, \'scope\': scope, \'metric\': metric, \'contrast\': name,\n                               \'estimate\': point[j], \'ci_low\': low[j], \'ci_high\': high[j],\n                               \'primary_familywise_ci_low\': flo[j] if primary else np.nan,\n                               \'primary_familywise_ci_high\': fhi[j] if primary else np.nan,\n                               \'primary\': primary, \'meanings\': len(means), \'paired_direction_meanings\': len(pivot),\n                               \'positive_means\': \'larger quality loss\' if quality else \'larger increase in metric\',\n                               \'interval\': \'whole meanings, fixed heads/languages/directions and 3 fixed controls; \'\n                                           \'primary COMET family uses Bonferroni across 3 models\'})\n            for sid, value in means[name].items():\n                per_meaning.append({\'study\': study, \'stage\': stage, \'scope\': scope, \'metric\': metric,\n                                    \'contrast\': name, \'sentence_id\': int(sid), \'value\': float(value)})\n    return pd.DataFrame(contrasts), pd.DataFrame(per_meaning)\n\n\ndef run(config):\n    import matplotlib\n    matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    output = Path(config[\'output\'])\n    output.mkdir(parents=True, exist_ok=True)\n    all_contrasts, all_meanings, all_conditions, by_target, jackknife, cap_rows = [], [], [], [], [], []\n    for study in config[\'studies\']:\n        collector = Path(config[\'collector_root\'])/study\n        score_root = Path(config[\'score_root\'])/study\n        complete = json.loads((collector/\'complete.json\').read_text())\n        quality_complete = json.loads((score_root/\'complete.json\').read_text())\n        require(sha_file(collector/\'teacher_forced.csv\') == complete[\'TF_sha256\'], \'TF input changed\')\n        require(sha_file(score_root/\'generation_scored.csv\') == quality_complete[\'scores_sha256\'], \'Quality labels changed\')\n        tf = pd.read_csv(collector/\'teacher_forced.csv\', dtype={\'corpus_sentence_id\': str})\n        gen = pd.read_csv(score_root/\'generation_scored.csv\', dtype={\'corpus_sentence_id\': str})\n        require(len(tf) == 13600 and len(gen) == 4000, \'Incomplete experimental grids\')\n        require(tf.sentence_id.nunique() == 68 and set(gen.sentence_id) == set(config[\'generation_ids\']), \'Changed meaning support\')\n        require(not tf.duplicated([\'sentence_id\', \'pair\', \'condition\']).any() and\n                not gen.duplicated([\'sentence_id\', \'pair\', \'condition\']).any(), \'Duplicate outcomes\')\n        for column in [\'off_target\', \'generation_hit_cap\', \'empty_output\', \'degenerate\', \'repeated_word_trigram\',\n                       \'changed_greedy_output\', \'changed_text\',\n                       \'source_truncated\', \'hypothesis_truncated\', \'reference_truncated\']:\n            gen[column] = bool_column(gen[column]).astype(float)\n        gen_metrics = [\'comet\', \'chrfpp\', \'off_target\', \'length_ratio_chars\', \'generation_hit_cap\',\n                       \'empty_output\', \'degenerate\', \'repeated_word_trigram\', \'changed_greedy_output\', \'changed_text\']\n        tf_metrics = [\'lexical_NLL\', \'sequence_NLL\', \'surviving_LM\', \'surviving_eos\', \'surviving_blank\']\n        for stage, frame, metrics in [(\'teacher_forced\', tf, tf_metrics), (\'generation\', gen, gen_metrics)]:\n            require(np.isfinite(frame[metrics]).all().all(), \'Nonfinite outcomes; do not drop rows\')\n            contrasts, values = compare(frame, metrics, stage, study, config[\'n_boot\'], config[\'seed\'], family_size=3)\n            all_contrasts.append(contrasts)\n            all_meanings.append(values)\n            for condition, group in frame.groupby(\'condition\', sort=False):\n                all_conditions.append({\'study\': study, \'stage\': stage, \'condition\': condition,\n                                       \'rows\': len(group), \'meanings\': group.sentence_id.nunique(),\n                                       **{metric: float(group[metric].mean()) for metric in metrics}})\n            # Conditional target-specific intervals are secondary; no separate significance claims.\n            targets = sorted(frame.target.unique())\n            for target in targets:\n                subset = frame[frame.target == target]\n                wanted = [\'comet\', \'chrfpp\', \'off_target\'] if stage == \'generation\' else [\'lexical_NLL\']\n                result, _ = compare(subset, wanted, stage, study, config[\'n_boot\'], config[\'seed\'],\n                                    scope=\'target=\'+target)\n                result[\'target\'] = target\n                by_target.append(result)\n                remaining = frame[frame.target != target]\n                for metric in wanted:\n                    pivot = remaining.pivot(index=[\'sentence_id\', \'pair\'], columns=\'condition\', values=metric)\n                    random = pivot[[\'random_1\', \'random_2\', \'random_3\']].mean(1)\n                    sign = 1 if metric in [\'comet\', \'chrfpp\'] else -1\n                    value = sign*(random-pivot.top_target_effect)\n                    jackknife.append({\'study\': study, \'stage\': stage, \'metric\': metric,\n                                      \'omitted_target\': target, \'selected_vs_random_mean\': float(value.mean()),\n                                      \'interpretation\': \'target omission, no head reranking/refit; \'\n                                                        \'does not establish new-language generalization\'})\n        # Primary includes all capped/empty outputs. Sensitivity requires all five paired conditions uncapped.\n        flags = gen.pivot(index=[\'sentence_id\', \'pair\'], columns=\'condition\', values=\'generation_hit_cap\')\n        good = flags.eq(0).all(1)\n        allowed = set(good[good].index)\n        clean = gen[[tuple(row) in allowed for row in gen[[\'sentence_id\', \'pair\']].to_numpy()]]\n        cap_rows.append({\'study\': study, \'primary_direction_meanings\': len(flags),\n                         \'all_conditions_uncapped_direction_meanings\': len(allowed),\n                         \'excluded_direction_meanings_in_sensitivity\': int((~good).sum()),\n                         \'primary_includes_cap_hits\': True})\n        if clean.sentence_id.nunique() >= 2:\n            result, _ = compare(clean, [\'comet\', \'chrfpp\', \'off_target\'], \'generation\', study,\n                                config[\'n_boot\'], config[\'seed\'], scope=\'all_conditions_uncapped_sensitivity\')\n            all_contrasts.append(result)\n        progress(study+\': paired effects, all11 targets and leave-one-target-out sensitivity complete\')\n    contrasts = pd.concat(all_contrasts, ignore_index=True)\n    atomic_csv(output/\'E5_ablation_contrasts.csv\', contrasts)\n    atomic_csv(output/\'E5_per_meaning_contrasts.csv\', pd.concat(all_meanings, ignore_index=True))\n    atomic_csv(output/\'E5_condition_means.csv\', pd.DataFrame(all_conditions))\n    atomic_csv(output/\'E5_target_specific_effects.csv\', pd.concat(by_target, ignore_index=True))\n    atomic_csv(output/\'E5_leave_one_target_out.csv\', pd.DataFrame(jackknife))\n    atomic_csv(output/\'E5_cap_sensitivity_support.csv\', pd.DataFrame(cap_rows))\n    primary = contrasts[contrasts.primary]\n    atomic_csv(output/\'E5_primary_COMET_selected_vs_random.csv\', primary)\n    fig, axes = plt.subplots(1, 3, figsize=(13, 4), constrained_layout=True)\n    for ax, metric, stage, title in zip(axes, [\'comet\', \'chrfpp\', \'lexical_NLL\'],\n                                        [\'generation\', \'generation\', \'teacher_forced\'],\n                                        [\'COMET loss: selected minus random\', \'chrF++ loss: selected minus random\',\n                                         \'NLL increase: selected minus random\']):\n        rows = contrasts[(contrasts.metric == metric) & (contrasts.stage == stage) &\n                         (contrasts.scope == \'all_directions\') & (contrasts.contrast == \'selected_vs_random_mean\')]\n        rows = rows.set_index(\'study\').loc[config[\'studies\']]\n        x = np.arange(len(rows))\n        ax.errorbar(x, rows.estimate, yerr=[np.maximum(0, rows.estimate-rows.ci_low),\n                                          np.maximum(0, rows.ci_high-rows.estimate)], fmt=\'o\', capsize=4)\n        ax.axhline(0, color=\'grey\', linewidth=.8)\n        ax.set_xticks(x, [study.upper() for study in rows.index])\n        ax.set_title(title, fontsize=10)\n        ax.set_ylabel(\'Paired mean difference; nominal 95% CI\')\n    for suffix in [\'png\', \'pdf\']:\n        fig.savefig(output/(\'E5_behavioral_ablation.\'+suffix), dpi=200)\n    plt.close(fig)\n    atomic_json(output/\'status.json\', {\'E5A_head_analysis_complete\': True, \'E5B_GPU_ablation_complete\': True,\n                 \'quality_evaluation_complete\': True, \'generation_meanings\': 20, \'TF_meanings\': 68,\n                 \'interpretation\': \'Read primary COMET contrasts and corrected intervals before claiming \'\n                                   \'selected heads affect quality more than matched controls. \'\n                                   \'This is whole-head ablation, not an EOS-specific intervention.\'})\n    progress(\'E5B numerical analysis complete. Positive primary effect = larger COMET loss for selected heads.\')\n    print(primary.to_string(index=False), flush=True)\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--config\', required=True)\n    run(json.loads(Path(parser.parse_args().config).read_text()))\n')


