# 3. Bounded live output; full logs stay in Drive. Agg is set before worker imports.
def run_live(command,environment=None,log_name='analysis.log'):
    OUTPUT_ROOT.mkdir(parents=True,exist_ok=True)
    destination=OUTPUT_ROOT/'private_logs';destination.mkdir(exist_ok=True)
    log_path=destination/log_name
    # Colab's inline backend is unavailable in this isolated worker. Set Agg
    # before Python imports matplotlib; matplotlib.use() alone is too late.
    child_environment=(os.environ if environment is None else environment).copy()
    child_environment['MPLBACKEND']='Agg'
    process=subprocess.Popen(command,env=child_environment,stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,text=True,bufsize=1,errors='replace')
    lines=queue.Queue();tail=deque(maxlen=20)
    started=time.monotonic();last_update=0.;last_heartbeat=started
    def reader():
        try:
            for line in process.stdout:lines.put(line)
        finally:lines.put(None)
    def refresh():
        clear_output(wait=True)
        display(HTML('<pre style="max-height:350px;overflow:auto">'+
            escape('\n'.join(tail)[-9000:])+'</pre>'))
    threading.Thread(target=reader,daemon=True).start()
    try:
        with log_path.open('a',encoding='utf-8') as log:
            while True:
                try:
                    line=lines.get(timeout=1)
                    if line is None:break
                    log.write(line);log.flush();tail.append(line.rstrip()[-2000:])
                except queue.Empty:pass
                now=time.monotonic()
                if now-last_heartbeat>=20:
                    text=f'Process alive {(now-started)/60:.1f} min; reading Drive parts or computing bootstrap.'
                    tail.append(text);log.write(text+'\n');log.flush();last_heartbeat=now
                if now-last_update>=2:refresh();last_update=now
        code=process.wait()
        if code:
            raise RuntimeError('Worker failed. Last output:\n'+'\n'.join(tail)+
                               '\nFull log: '+str(log_path))
    except BaseException:
        if process.poll() is None:
            process.terminate()
            try:process.wait(timeout=10)
            except subprocess.TimeoutExpired:process.kill();process.wait()
        raise
    finally:
        refresh()
        print('Full log:',log_path)


