# 4. Prepare the pinned MT environment and Indic normalization resources.
run_live(['nvidia-smi','--query-gpu=name,memory.total','--format=csv,noheader'],environment,'GPU.log')
run_live([sys.executable,'-m','pip','install','--quiet','uv==0.9.7'],environment,'setup.log')
UV=[sys.executable,'-m','uv']
def prepare_environment(path,python,lock,extra):
    if not python.is_file():
        run_live(UV+['python','install','3.12'],environment,'setup.log')
        run_live(UV+['venv','--python','3.12',str(path)],environment,'setup.log')
    run_live(UV+['pip','install','--python',str(python),'--extra-index-url','https://download.pytorch.org/whl/cu121',
        '--index-strategy','unsafe-best-match','-r',str(STAGING/lock)]+extra,environment,'setup.log')
    # Record the complete installed environment, including transitive plotting/LID packages.
    freeze_name=OUTPUT_ROOT/(path.name+'_packages.txt')
    packages=subprocess.check_output(UV+['pip','freeze','--python',str(python)],env=environment,text=True)
    if freeze_name.exists():require(freeze_name.read_text()==packages,'Installed package set changed; inspect before resuming')
    else:freeze_name.write_text(packages,encoding='utf-8')
prepare_environment(MT_ENV,MT_PYTHON,'mt_environment_lock.txt',['matplotlib==3.9.4'])
def pinned_checkout(name,url,revision):
    path=DEPENDENCIES/name
    if not (path/'.git').is_dir():
        path.mkdir(parents=True,exist_ok=True)
        run_live(['git','init',str(path)],environment,'setup.log')
        run_live(['git','-C',str(path),'remote','add','origin',url],environment,'setup.log')
    found=subprocess.run(['git','-C',str(path),'rev-parse','HEAD'],capture_output=True,text=True)
    if found.returncode:
        run_live(['git','-C',str(path),'fetch','--depth','1','origin',revision],environment,'setup.log')
        run_live(['git','-C',str(path),'checkout','--detach',revision],environment,'setup.log')
    actual=subprocess.check_output(['git','-C',str(path),'rev-parse','HEAD'],text=True).strip()
    require(actual==revision,'Normalization dependency revision changed: '+name)
    return path
INDIC_LIBRARY=pinned_checkout('indic_nlp_library','https://github.com/anoopkunchukuttan/indic_nlp_library.git',
                             '4cead0ae6c78fe9a19a51ef679f586206df9c476')
