# 5. Run each model in its own process. Conditions/partial generations resume automatically.
def collector_complete(study):
    root=OUTPUT_ROOT/'collectors'/study;path=root/'complete.json'
    if not path.is_file():return False
    saved=json.loads(path.read_text())
    require(sha_file(root/'run_lock.json')==saved['run_lock_sha256'],'Changed collector lock')
    require(sha_file(root/'teacher_forced.csv')==saved['TF_sha256'],'Changed TF outputs')
    require(sha_file(root/'private_generation/all_outputs.csv')==saved['generation_sha256'],'Changed generation outputs')
    require(json.loads((root/'run_lock.json').read_text())['source_hashes']==SOURCE_HASHES,'Completed collector code changed')
    return True
for study in STUDIES:
    if collector_complete(study):
        progress(study+': verified completed collection; skipping GPU inference');continue
    config={**COMMON,'study':study,'output':str(OUTPUT_ROOT/'collectors'/study),'selection':selection[study],
        'e4_rows_sha256':e4_completion[study]['all_rows_sha256'],
        'token_ids_sha256':e4_completion[study]['token_ids_sha256'],
        'indic_library':str(INDIC_LIBRARY),'indic_resources':str(INDIC_RESOURCES),
        'madlad_cache':'/content/drive/MyDrive/indic_40_model_cache/madlad400_3b_fa184c675da0'}
    path=STAGING/(study+'_collector.json');atomic_json(path,config)
    run_live([str(MT_PYTHON),'-u',str(STAGING/'e5_ablation_worker.py'),'--config',str(path)],
             environment,study+'_collector.log')
    require(collector_complete(study),'Incomplete model collection: '+study)
print(pd.DataFrame([{'study':s,**json.loads((OUTPUT_ROOT/'collectors'/s/'smoke_report.json').read_text())}
                    for s in STUDIES]).to_string(index=False))


