# 8. Verify completion, save a manifest and create the result archive.
require(all(collector_complete(s) for s in STUDIES) and scores_complete(),'Incomplete experimental outputs')
status=json.loads((OUTPUT_ROOT/'analysis/status.json').read_text())
require(status['E5B_GPU_ablation_complete'] and status['quality_evaluation_complete'],'Analysis incomplete')
atomic_json(OUTPUT_ROOT/'status.json',status)
files=[]
for path in sorted(OUTPUT_ROOT.rglob('*')):
    if not path.is_file() or path.name=='completed_all.json' or path.suffix in {'.tmp','.zip'}:continue
    relative=path.relative_to(OUTPUT_ROOT)
    if any(part in {'private_generation','private_text_cache','private_logs','parts','__pycache__'} for part in relative.parts):continue
    files.append(path)
atomic_json(OUTPUT_ROOT/'completed_all.json',{'experiment':'E5B','status':status,
    'files':{str(path.relative_to(OUTPUT_ROOT)):sha_file(path) for path in files}})
archive=OUTPUT_ROOT.with_name(OUTPUT_ROOT.name+'_results.zip');temporary=archive.with_suffix('.tmp.zip')
with zipfile.ZipFile(temporary,'w',compression=zipfile.ZIP_DEFLATED) as bundle:
    for path in files+[OUTPUT_ROOT/'completed_all.json']:
        bundle.write(path,str(path.relative_to(OUTPUT_ROOT)))
temporary.replace(archive)
print(json.dumps(status,indent=2))
print('Results:',OUTPUT_ROOT)
print('Archive:',archive)
